<?php require_once __DIR__.'/includes/functions.php'; $title='Attractions'; include __DIR__.'/includes/header.php'; $destination=(int)($_GET['destination']??0); $q=trim((string)($_GET['q']??'')); $stmt=db()->prepare("SELECT a.*,d.name destination_name FROM attractions a JOIN destinations d ON d.id=a.destination_id WHERE a.status='active' AND (?=0 OR a.destination_id=?) AND (?='' OR a.name LIKE ? OR a.short_description LIKE ?) ORDER BY a.display_order,a.name"); $like='%'.$q.'%'; $stmt->execute([$destination,$destination,$q,$like,$like]); $rows=$stmt->fetchAll(); ?>
<main class="container py-5"><div class="d-flex justify-content-between align-items-center flex-wrap gap-3"><div><h1 class="display-serif">Attractions</h1><p class="text-muted">Places worth remembering.</p></div><form class="d-flex"><input class="form-control" name="q" value="<?=e($q)?>" placeholder="Search attractions"><button class="btn btn-success">Search</button></form></div><div class="row g-4 mt-2"><?php foreach($rows as $a): ?><div class="col-md-6 col-lg-4"><article class="card h-100"><?php if($a['main_image']): ?><img class="card-img-top" src="<?=e($a['main_image'])?>" alt="<?=e($a['name'])?>" loading="lazy"><?php endif; ?><div class="card-body d-flex flex-column"><small class="text-success"><?=e($a['destination_name'])?></small><h2 class="h4"><?=e($a['name'])?></h2><p><?=e($a['short_description'])?></p><a href="attraction.php?slug=<?=e($a['slug'])?>" class="btn btn-success mt-auto">More information</a></div></article></div><?php endforeach; ?></div></main><?php include __DIR__.'/includes/footer.php'; ?>
